(async () => {
  const code = await (await fetch('/history/landView.ts')).text();
  const url = (name) => { const m = code.match(new RegExp('"(/@fs/[^"]*/src/shared/history/' + name + '\\.ts[^"]*)"')); return m ? m[1] : null; };
  const base = url('fold').replace(/fold\.ts.*$/, '');
  const F = await import(base + 'fold.ts'); const B = await import(base + 'beat.ts');
  const S = await import('/state/index.ts'); const w = S.useHistoryStore.getState().world.value;
  const r = await window.seed.world.read(w.worldId); const es = r.value.entries;
  const genesis = F.openGenesis(r.value.genesis).value;
  const out = [];
  for (const be of es.filter((e) => e.entry.event.kind === 'beat')) {
    const body = be.entry.event.body;
    const upto = F.foldEntries(F.emptyNow(genesis), es.filter((e) => e.entry.n <= body.upTo));
    const c = B.computeBeat(upto, body.at);
    out.push({ n: be.entry.n, upTo: body.upTo, logged: body.fingerprint, recomputed: c.ok ? c.value.body.fingerprint : c.error.code, equal: c.ok && JSON.stringify(c.value.body) === JSON.stringify(body) });
  }
  return JSON.stringify({ me: w.status.me.slice(0, 12), head: w.now.head, beats: out, ignored: w.now.ignored });
})()

